<script lang="ts">
 import {textDiff} from '../domain/text-diff';
 import {onMount} from 'svelte';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {noticeText,failureCode} from '$lib/shared/presentation/copy';
 import type {TitleChangesGateway,TitleChangeDetail,ProposedTitleData} from '../application/title-changes';
 import type {Taxonomy} from '../application/catalog';
 import {catalogNames} from './messages';
 let {gateway,id}:{gateway:TitleChangesGateway;id:string}=$props();
 const {locale}=useLocale();const names=$derived(catalogNames($locale));
 let actor=$state(''),detail=$state<TitleChangeDetail|null>(null),taxonomy=$state<Taxonomy>({genres:[],categories:[],collections:[]}),loading=$state(true),busy=$state(false),error=$state(''),reason=$state('');let generation=0;
 const status=$derived({pending:text($locale,'Қаралуда','На рассмотрении'),approved:text($locale,'Мақұлданды','Одобрено'),rejected:text($locale,'Қайтарылды','Возвращено')});
 const labels=$derived<Record<keyof ProposedTitleData,string>>({name:text($locale,'Атауы','Название'),original_name:text($locale,'Түпнұсқа атауы','Оригинальное название'),aliases:text($locale,'Басқа атаулар','Другие названия'),authors:text($locale,'Авторлар','Авторы'),kind:text($locale,'Түрі','Тип'),original_status:text($locale,'Тайтл күйі','Статус тайтла'),translation_status:text($locale,'Аударма күйі','Статус перевода'),description:text($locale,'Сипаттама','Описание'),direction:text($locale,'Оқу бағыты','Направление чтения'),age_rating:text($locale,'Жас шектеуі','Возрастная маркировка'),publication:text($locale,'Басылым','Издание'),genre_ids:text($locale,'Жанрлар','Жанры'),category_ids:text($locale,'Санаттар','Категории')});
 const changed=$derived(detail?(Object.keys(labels) as (keyof ProposedTitleData)[]).filter(key=>JSON.stringify(detail!.request.before.data[key])!==JSON.stringify(detail!.request.proposed[key])):[]);
 function format(data:ProposedTitleData,key:keyof ProposedTitleData):string{const value=data[key];if(key==='kind')return names.kind[data.kind];if(key==='original_status')return names.original[data.original_status];if(key==='translation_status')return names.translation[data.translation_status];if(key==='genre_ids'||key==='category_ids'){const items=key==='genre_ids'?taxonomy.genres:taxonomy.categories;return (value as string[]).map(id=>items.find(x=>x.id===id)?.name||id).join(', ')||'—';}if(key==='publication'){const p=data.publication;return [p.year||'',...p.publishers,p.source,p.country,...p.formats,...p.links.map(x=>x.label+': '+x.url)].filter(Boolean).join('\n')||'—';}if(key==='direction')return value==='ltr'?text($locale,'Солдан оңға','Слева направо'):text($locale,'Оңнан солға','Справа налево');if(key==='age_rating')return value?value+'+':'—';return Array.isArray(value)?value.join('\n')||'—':String(value||'—');}
 async function load(){const run=++generation;loading=true;detail=null;actor='';reason='';error='';try{const account=await gateway.currentAccount();if(!account)throw Error('unauthorized');const [item,taxa]=await Promise.all([gateway.detail(account,id),gateway.taxonomy()]);if(run!==generation)return;actor=account;detail=item;taxonomy=taxa;}catch(e){if(run===generation)error=failureCode(e);}finally{if(run===generation){loading=false;busy=false;}}}
 async function review(decision:'approve'|'reject'){if(!detail||busy)return;busy=true;error='';const run=generation;try{await gateway.review(actor,id,decision,reason);if(run===generation)await load();}catch(e){if(run===generation)error=failureCode(e);}finally{if(run===generation)busy=false;}}
 onMount(()=>{void load();const stop=gateway.watchAccount(()=>{busy=false;void load();});return()=>{generation++;stop();};});
</script>
<svelte:head><title>{text($locale,'Тайтл өзгерістері','Изменения тайтла')} — Qmanga</title></svelte:head>
<h1>{text($locale,'Тайтл өзгерістері','Изменения тайтла')}</h1>
{#if loading}<p role="status">{text($locale,'Жүктелуде…','Загрузка…')}</p>{/if}
{#if error}<p class="notice" role="alert">{noticeText($locale,error)}</p><button class="button subtle" onclick={load}>{text($locale,'Қайта жүктеу','Обновить')}</button>{/if}
{#if detail}
 <header><h2>{detail.request.title_name}</h2><p>{detail.request.team_name} · {detail.request.requested_name}</p><strong>{status[detail.request.status]}</strong></header>
 <section class="panel"><h2>{text($locale,'Негіздеме','Обоснование')}</h2><p class="preserve">{detail.request.reason}</p>
 {#each detail.request.links as link}<p class="source"><a href={link} target="_blank" rel="noopener noreferrer">{link}</a></p>{/each}
 <div class="evidence">{#each detail.request.assets.filter(a=>a.purpose==='evidence') as asset}<a href={asset.url} target="_blank" rel="noopener noreferrer"><img src={asset.url} alt={text($locale,'Дәлел суреті','Изображение доказательства')} loading="lazy"/></a>{/each}</div></section>
 {#if changed.length}<section class="changes"><h2>{text($locale,'Ұсынылған өзгерістер','Предлагаемые изменения')}</h2>{#each changed as key}<article class="panel"><h3>{labels[key]}</h3><div class="comparison"><div><h4>{text($locale,'Өтінім берілгенде','На момент подачи')}</h4><p>{#each textDiff(format(detail.request.before.data,key),format(detail.request.proposed,key)).before as part}{#if part.changed}<del>{part.text}</del>{:else}{part.text}{/if}{/each}</p></div><div><h4>{text($locale,'Қазір','Сейчас')}</h4><p>{format(detail.current.data,key)}</p></div><div><h4>{text($locale,'Ұсынылғаны','Предлагается')}</h4><p>{#each textDiff(format(detail.request.before.data,key),format(detail.request.proposed,key)).after as part}{#if part.changed}<ins>{part.text}</ins>{:else}{part.text}{/if}{/each}</p></div></div></article>{/each}</section>{/if}
 {#each ['cover','banner'] as kind}{@const action=detail.request[kind==='cover'?'cover_action':'banner_action']}{#if action!=='keep'}<section class="panel"><h2>{kind==='cover'?text($locale,'Мұқаба','Обложка'):text($locale,'Баннер','Баннер')}</h2><p>{action==='remove'?text($locale,'Алып тастау ұсынылады','Предлагается удалить'):text($locale,'Ауыстыру ұсынылады','Предлагается заменить')}</p><div class="artwork">{#if detail.current[kind==='cover'?'cover_id':'banner_id']}<figure><figcaption>{text($locale,'Қазір','Сейчас')}</figcaption><img src={'/api/v1/media/'+encodeURIComponent(detail.current[kind==='cover'?'cover_id':'banner_id'])} alt={text($locale,'Қазіргі сурет','Текущее изображение')}/></figure>{/if}{#each detail.request.assets.filter(a=>a.purpose===kind) as asset}<figure><figcaption>{text($locale,'Ұсынылғаны','Предлагается')}</figcaption><img src={asset.url} alt={text($locale,'Ұсынылған сурет','Предлагаемое изображение')}/></figure>{/each}</div></section>{/if}{/each}
 {#if detail.request.status==='pending'&&detail.can_review}
 <section class="panel"><h2>{text($locale,'Модератор шешімі','Решение модератора')}</h2>{#if detail.current_version!==detail.request.base_version}<p class="notice" role="status">{text($locale,'Өтінім берілгеннен кейін карточка өзгерді. Ескірген өзгерістерді мақұлдауға болмайды.','После подачи заявки карточка изменилась. Устаревшие изменения нельзя одобрить.')}</p>{/if}
 <label>{text($locale,'Шешімнің себебі · қайтарғанда міндетті','Причина решения · обязательна при возврате')}<textarea bind:value={reason} rows="3" maxlength="2000" disabled={busy}></textarea></label>
 <div class="actions"><button class="button primary" disabled={busy||detail.current_version!==detail.request.base_version} onclick={()=>review('approve')}>{text($locale,'Мақұлдау','Одобрить')}</button><button class="button subtle" disabled={busy||reason.trim().length<3} onclick={()=>review('reject')}>{text($locale,'Қайтару','Вернуть')}</button></div></section>
 {:else if detail.request.status!=='pending'}<section class="panel"><h2>{text($locale,'Шешім','Решение')}</h2><p>{detail.request.reviewed_name}</p><p class="preserve">{detail.request.resolution||status[detail.request.status]}</p></section>{/if}
 {#if detail.request.project_id}<a class="button subtle" href={'/studio/projects/'+encodeURIComponent(detail.request.project_id)+'/metadata'}>{text($locale,'Жоба өтінімдері','Заявки проекта')}</a>{/if}
{/if}
<style>del,ins{font-weight:650;text-decoration-thickness:2px}ins{background:var(--raised);text-decoration-style:double}del{text-decoration-style:solid}h1{font-size:24px}.panel{margin-block:16px;min-width:0}.panel h2{font-size:19px;margin-top:0}h3{font-size:16px}h4{font-size:12px;color:var(--muted);font-weight:500;margin-block:8px}.comparison{display:grid;gap:12px}.comparison p,.preserve{white-space:pre-wrap;overflow-wrap:anywhere;margin-block:8px}.comparison>div{min-width:0}.source{overflow-wrap:anywhere}.evidence,.artwork{display:flex;gap:16px;flex-wrap:wrap}.evidence a{display:block;min-width:44px}.evidence img{max-width:180px;max-height:220px;object-fit:contain}.artwork figure{margin:0;max-width:100%}.artwork img{display:block;max-width:min(100%,320px);max-height:280px;object-fit:contain;margin-top:8px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:16px}label{display:grid;gap:8px}.notice{padding:12px;border:1px solid var(--line);border-radius:8px}@media(min-width:900px){.comparison{grid-template-columns:repeat(3,minmax(0,1fr))}}</style>
